const servers = ref([
  { name: 'github', latency: '12 ms', state: '健康', tone: 'healthy' },
  { name: 'filesystem', latency: '3 ms', state: '健康', tone: 'healthy' },
  { name: 'postgres', latency: '41 ms', state: '健康', tone: 'healthy' },
  { name: 'slack', latency: '180 ms', state: '降级', tone: 'degraded' },
  { name: 'browser', latency: '—', state: '熔断', tone: 'offline' },
])
const activeSource = ref('all')
const query = ref('')
const selected = ref(tools[0])
const detailTab = ref('契约')
const gateWrite = ref(true)
const gateExternal = ref(true)
const gateDestructive = ref(false)
const toast = ref('')
const visibleTools = computed(() => tools.filter(tool => (activeSource.value === 'all' || tool.source === activeSource.value) && `${tool.name} ${tool.group} ${tool.owner}`.toLowerCase().includes(query.value.trim().toLowerCase())))
const budgetPercent = computed(() => Math.round(tools.length / 64 * 100))
const gatedCount = computed(() => tools.filter(tool => (gateWrite.value && tool.risk === 'W') || (gateExternal.value && tool.risk === 'X') || (gateDestructive.value && tool.risk === 'D')).length)

watch([activeSource, query], () => {
  if (!visibleTools.value.some(tool => tool.name === selected.value?.name)) selected.value = visibleTools.value[0] || null
})

function notify(message) {
  toast.value = message
  window.clearTimeout(notify.timer)
  notify.timer = window.setTimeout(() => { toast.value = '' }, 2600)
}
function selectSource(id) {
  activeSource.value = id
  if (!visibleTools.value.some(tool => tool.name === selected.value?.name)) selected.value = visibleTools.value[0] || null
}
function selectTool(tool) {
  selected.value = tool
  detailTab.value = '契约'
}
function reconnectServers() {
  servers.value = servers.value.map(server => ({ ...server, state: server.name === 'browser' ? '半开试探' : '健康', tone: server.name === 'browser' ? 'degraded' : 'healthy', latency: server.name === 'browser' ? '—' : server.latency }))
  notify('已发送本地演示重连请求')
}
function toggleBreaker(server) {
  if (server.name !== 'browser') return
  server.state = server.tone === 'offline' ? '半开试探' : '熔断'
  server.tone = server.tone === 'offline' ? 'degraded' : 'offline'
  notify(`browser Server 已切换为${server.state}（演示）`)
}
